import Foundation

/// The genre families and their styles, as the Discogs community publishes them (a two-level taxonomy: broad genres and the styles under them; a release can carry several, so a style
/// can sit under more than one family). The list comes from the taxonomy file of the ISMIR 2017 Discogs study; it is data, not something the app decides. MusicBrainz's own genre list
/// has no hierarchy, so it is not used for relationships. Generated from that file: do not edit by hand.
struct MusicGenreFamily: Hashable, Identifiable, Sendable {
    var name: String
    var styles: [String]
    var id: String { name }
}

